* {
    box-sizing: border-box;
}

.tarjeta {
    width: 80%;
    max-width: 500px;
    padding: 20px;
    border: 2px solid brown;
    margin: 30px auto;
}

button {
    background-color: brown;
    color: white;
    padding: 10px 16px;
    border: none;
}

button:hover {
    background-color: darkred;
}

button:active {
    background-color: black;
}

button:focus {
    outline: 3px solid orange;
}

.tarjeta {
    position: relative;
}

.etiqueta {
    position: absolute;
    top: 10px;
    right: 10px;
    background-color: #8B0000;
    color: white;
    padding: 5px 8px;
}

nav {
    position: sticky;
    top: 0;
    background-color: white;
    padding: 10px;
    z-index: 10;
}

.contenedor {
    border: 3px solid #1e3c78;
    min-height: 250px;
}

.caja {
    padding: 20px;
    border: 2px solid #14785a;
    background-color: #e8faf5;
}

justify-content: flex-start;
justify-content: flex-end;
justify-content: space-between;
justify-content: space-around;
justify-content: space-evenly;

.contenedor {
    display: flex;
    flex-wrap: wrap;
    gap: 20px;
    height: 500px;
    align-content: center;
}

.servicios {
    display: flex;
    flex-wrap: wrap;
    gap: 20px;
}

.tarjeta {
    flex: 1 1 250px;
    display: flex;
    flex-direction: column;
    padding: 20px;
    border: 1px solid gray;
}

.tarjeta button {
    margin-top: auto;
}

.rejilla {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    grid-template-rows: 120px;
    grid-auto-rows: minmax(120px, auto);
    gap: 1rem;
}

.rejilla {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    grid-auto-flow: row;
}

.rejilla {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    grid-auto-flow: row dense;
}

.pagina {
    display: grid;
    grid-template-columns:
        [inicio] 240px
        [contenido-inicio] 1fr
        [fin];
}

.lateral {
    grid-column: inicio / contenido-inicio;
}

.contenido {
    grid-column: contenido-inicio / fin;
}

.pagina {
    display: grid;
    grid-template-columns: 240px 1fr;
    grid-template-areas:
        "cabecera cabecera"
        "lateral  contenido"
        "pie      pie";
}

.cabecera  { grid-area: cabecera; }
.lateral   { grid-area: lateral; }
.contenido { grid-area: contenido; }
.pie       { grid-area: pie; }

.rejilla {
    display: grid;
    grid-template-columns:
        repeat(auto-fit, minmax(240px, 1fr));
    gap: 1rem;
}

.galeria {
    display: grid;
    grid-template-columns: repeat(3, minmax(0, 1fr));
    gap: 1rem;
}

.tarjetas {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 1rem;
}

.tarjeta--destacada {
    grid-column: span 2;
}

.pagina {
    display: grid;
    grid-template-columns: 220px 1fr;
    grid-template-areas:
        "nav main"
        "nav footer";
}

.hero {
    display: grid;
}

.hero__imagen,
.hero__contenido {
    grid-area: 1 / 1;
}

.hero__contenido {
    z-index: 1;
    align-self: end;
}
